const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8090';

class ApiClient {
  private token: string | null = null;

  setToken(token: string) {
    console.log('ApiClient - setToken called with token:', token.substring(0, Math.min(token.length, 20)) + '...');
    this.token = token;

    // Временно используем localStorage вместо cookies
    localStorage.setItem('accessToken', token);
    console.log('ApiClient - Token saved to localStorage');
  }

  setRefreshToken(refreshToken: string) {
    console.log('ApiClient - setRefreshToken called');
    localStorage.setItem('refreshToken', refreshToken);
    console.log('ApiClient - RefreshToken saved to localStorage');
  }

  getRefreshToken() {
    return localStorage.getItem('refreshToken');
  }

  getToken() {
    if (!this.token) {
      // Читаем токен из localStorage вместо cookies
      this.token = localStorage.getItem('accessToken');
      console.log('ApiClient - Token loaded from localStorage:', this.token ? this.token.substring(0, Math.min(this.token.length, 20)) + '...' : 'NULL');
    }
    return this.token;
  }

  clearToken() {
    this.token = null;
    document.cookie = 'accessToken=; path=/; expires=Thu, 01 Jan 1970 00:00:01 GMT';
    localStorage.removeItem('accessToken');
  }

  private async request<T>(
    endpoint: string,
    options: RequestInit = {}
  ): Promise<T> {
    const url = `${API_BASE_URL}${endpoint}`;
    const token = this.getToken();

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const requestHeaders = {
      ...headers,
      ...(options.headers as Record<string, string> || {}),
    };

    console.log('API Request - URL:', url);
    console.log('API Request - Headers:', requestHeaders);
    console.log('API Request - Token exists:', !!token);
    if (token) {
      console.log('API Request - Token first 20 chars:', token.substring(0, 20) + '...');
    }

    const response = await fetch(url, {
      ...options,
      headers: requestHeaders,
    });

    const responseText = await response.text();
    console.log('Raw response:', responseText);

    if (!response.ok) {
      let error;
      try {
        error = responseText ? JSON.parse(responseText) : {};
        console.error('Parsed error:', error);
      } catch (parseError) {
        console.error('JSON parse error:', parseError);
        error = { error: 'Failed to parse error response' };
      }

      console.error('API Error Details:', {
        status: response.status,
        statusText: response.statusText,
        error: error
      });
      throw new Error(error.message_text || error.message || error.mesage || error.error || `API Error: ${response.status} - ${response.statusText}`);
    }

    try {
      // Проверяем, является ли ответ JSON
      if (responseText && (responseText.trim().startsWith('{') || responseText.trim().startsWith('['))) {
        const result = JSON.parse(responseText);
        console.log('API Success Response (JSON):', result);
        return result as T;
      } else {
        // Если это не JSON, возвращаем как строку
        console.log('API Success Response (String):', responseText);
        return responseText as unknown as T;
      }
    } catch (parseError) {
      console.error('JSON parse error on success response:', parseError);
      // Если парсинг не удался, возвращаем как строку
      console.log('Returning response as string:', responseText);
      return responseText as unknown as T;
    }
  }

  get<T>(endpoint: string, options?: RequestInit) {
    return this.request<T>(endpoint, { ...options, method: 'GET' });
  }

  post<T>(endpoint: string, data?: any, options?: RequestInit) {
    return this.request<T>(endpoint, {
      ...options,
      method: 'POST',
      body: data ? JSON.stringify(data) : undefined,
    });
  }

  put<T>(endpoint: string, data?: any, options?: RequestInit) {
    return this.request<T>(endpoint, {
      ...options,
      method: 'PUT',
      body: data ? JSON.stringify(data) : undefined,
    });
  }

  patch<T>(endpoint: string, data?: any, options?: RequestInit) {
    return this.request<T>(endpoint, {
      ...options,
      method: 'PATCH',
      body: data ? JSON.stringify(data) : undefined,
    });
  }

  delete<T>(endpoint: string, options?: RequestInit) {
    return this.request<T>(endpoint, { ...options, method: 'DELETE' });
  }
}


export const apiClient = new ApiClient();
